// CMP-05: EduOS service level objectives, defined once. The Prometheus rules
// (monitoring/eduos-slo.yml, generated by scripts/generate-slo-rules.mjs) and
// the monthly report (src/slo-report.js) are both built from this file.
//
// These are proposed internal targets for running the service, not a
// contractual SLA: a district agrees its own targets and support hours.
// Every SLI uses only the aggregate metrics /metrics already exports (method,
// route template, status class, latency bucket, scrape up); no district,
// school, user or student label exists to leak.

export const JOB = "eduos";

/** Route templates that don't measure user-facing service. */
const MONITORING_ROUTES = ["/metrics", "/health", "/api/operations/stream"]; // scrapes, health checks, a long-lived event stream
/** Requests that wait on an AI provider; slow by design, so excluded from the latency SLI only. */
const AI_ROUTES = ["/api/ai/run", "/api/christie/sessions/:id/turns", "/api/edison/brief", "/api/leo/drafts"];

export const AVAILABILITY_EXCLUDED_ROUTES = MONITORING_ROUTES;
export const LATENCY_EXCLUDED_ROUTES = [...MONITORING_ROUTES, ...AI_ROUTES];
export const LATENCY_THRESHOLD_SECONDS = 1; // must be one of metrics.js LATENCY_BUCKETS

export const PERIOD_DAYS = 30;

export const SLOS = [
  { id: "availability", objective: 0.999, title: "Requests succeed",
    description: "API requests that don't fail with a server error (5xx)." },
  { id: "latency", objective: 0.99, title: `Requests answered within ${LATENCY_THRESHOLD_SECONDS}s`,
    description: `API requests answered within ${LATENCY_THRESHOLD_SECONDS} second (AI-generation requests excluded).` },
  { id: "uptime", objective: 0.999, title: "Service reachable",
    description: "Minutes in which Prometheus could scrape at least one EduOS API instance." }
];

const re = routes => routes.map(r => r.replace(/[.*+?^${}()|[\]\\]/g, "\\\\$&")).join("|");
const sel = (routes, extra = "") => `job="${JOB}",route!~"${re(routes)}"${extra}`;

/** PromQL for one SLO's bad and total event rates over `win` (e.g. "5m"); uptime is handled separately. */
export function sliQueries(id, win) {
  if (id === "availability") {
    const s = sel(AVAILABILITY_EXCLUDED_ROUTES);
    return { total: `sum(rate(eduos_http_requests_total{${s}}[${win}]))`,
      bad: `sum(rate(eduos_http_requests_total{${sel(AVAILABILITY_EXCLUDED_ROUTES, ',status="5xx"')}}[${win}]))` };
  }
  if (id === "latency") {
    const s = sel(LATENCY_EXCLUDED_ROUTES);
    return { total: `sum(rate(eduos_http_request_duration_seconds_count{${s}}[${win}]))`,
      bad: `sum(rate(eduos_http_request_duration_seconds_count{${s}}[${win}])) - sum(rate(eduos_http_request_duration_seconds_bucket{${sel(LATENCY_EXCLUDED_ROUTES, `,le="${LATENCY_THRESHOLD_SECONDS}"`)}}[${win}]))` };
  }
  throw new Error(`no request SLI for ${id}`);
}

/** Bad-event ratio over a whole reporting window, from raw counters (for reports). */
export function reportQuery(id, days) {
  const win = `${days}d`;
  if (id === "uptime") return `1 - avg_over_time(max(up{job="${JOB}"})[${win}:1m])`;
  const q = sliQueries(id, win);
  const inc = s => s.replaceAll("rate(", "increase(");
  return `(${inc(q.bad)}) / clamp_min(${inc(q.total)}, 1)`;
}
export function reportTrafficQuery(id, days) {
  if (id === "uptime") return `count_over_time(max(up{job="${JOB}"})[${days}d:1m])`;
  return sliQueries(id, `${days}d`).total.replaceAll("rate(", "increase(");
}

/**
 * Multi-window, multi-burn-rate alerts (Google SRE Workbook, ch. 5). Burn rate
 * 1 spends exactly the 30-day budget in 30 days; 14.4 spends 2% of it in an hour.
 */
export const BURN_ALERTS = [
  { name: "Fast", long: "1h", short: "5m", burn: 14.4, for: "2m", severity: "critical", spends: "2% of the 30-day error budget in an hour" },
  { name: "Steady", long: "6h", short: "30m", burn: 6, for: "15m", severity: "critical", spends: "5% of the 30-day error budget in six hours" },
  { name: "Slow", long: "1d", short: "2h", burn: 3, for: "1h", severity: "warning", spends: "10% of the 30-day error budget in a day" },
  { name: "Creeping", long: "3d", short: "6h", burn: 1, for: "3h", severity: "warning", spends: "the 30-day error budget at the rate it is being earned" }
];
/** Below this many requests per second over the long window, a few failures shouldn't page anyone at 3 a.m. */
export const MIN_ALERT_RPS = 0.01; // 36 requests an hour
